WITH parsed AS (SELECT id, service, log_ts, level, latency_ms, context['trace'] AS trace, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, COALESCE(context['trace'], 'none') AS trace_or_default FROM app_logs WHERE level IN ('WARN', 'ERROR')) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, service, COUNT(*) AS event_count, SUM(CASE WHEN service = 'checkout' THEN latency_ms ELSE 0 END) AS checkout_latency_ms, SORT_ARRAY(COLLECT_SET(service)) AS service_list, SUM(retry_count) FILTER (WHERE service = 'billing') AS billing_total_retry_count, COUNT(*) FILTER (WHERE level = 'INFO') AS info_rows FROM parsed GROUP BY 1, 2 HAVING COUNT(*) FILTER (WHERE level = 'INFO') < 1000 ORDER BY service DESC;
